import sys

def find_fingering(n, notes):
    if n == 1:
        return [1]

    # Initialize the fingering array
    fingering = [0] * n

    # Start with the first finger
    fingering[0] = 1

    # Fill the fingering array
    for i in range(1, n):
        if notes[i] > notes[i - 1]:
            # Increasing note, use the next available finger
            fingering[i] = fingering[i - 1] + 1
            if fingering[i] > 5:
                return [-1]
        elif notes[i] < notes[i - 1]:
            # Decreasing note, use the previous available finger
            fingering[i] = fingering[i - 1] - 1
            if fingering[i] < 1:
                return [-1]
        else:
            # Same note, use a different finger
            if fingering[i - 1] == 5:
                fingering[i] = 4
            else:
                fingering[i] = fingering[i - 1] + 1

    return fingering

